/* eslint-disable jsx-a11y/anchor-is-valid */
import "./home.css";
import { ShoppingCart, User } from "lucide-react"; // Import the icons

const HomePage = () => {
  return (
    <section className="nav-bar">
      <div className="nav-bar-links-menu-left">
        <a href="#">Home</a>
        <a href="#">About Us</a>
        <a href="#">Store</a>
      </div>
      <div className="nav-bar-links-menu-right">
        <a href="#">
          <ShoppingCart size={20} />
        </a>
        <a href="#">
          <User size={20} />
        </a>
      </div>
    </section>
  );
};

export default HomePage;
